2|import { requireConfig } from './config';
3|export class HttpError extends Error { constructor(public status: number, message: string) { super(message); } }
4|export function checkOrigin(request: Request) {
5| if (request.headers.get('origin') !== requireConfig().origin) throw new HttpError(403, 'Požadavek není ze stejného webu.');
6| if (request.headers.get('sec-fetch-site') === 'cross-site') throw new HttpError(403, 'Požadavek není ze stejného webu.');
7|}
8|export async function readJson(request: Request, maxBytes = 16384): Promise<unknown> {
9| checkOrigin(request);
10| if (request.headers.get('content-type')?.split(';')[0].trim().toLowerCase() !== 'application/json') throw new HttpError(415, 'Vyžadujeme JSON.');
11| if (Number(request.headers.get('content-length')) > maxBytes) throw new HttpError(413, 'Požadavek je příliš velký.');
12| const reader = request.body?.getReader();
13| if (!reader) throw new HttpError(400, 'Chybí tělo požadavku.');
14| const chunks: Uint8Array[] = []; let size = 0;
15| try { while (true) { const { done, value } = await reader.read(); if (done) break; size += value.byteLength; if (size > maxBytes) { await reader.cancel(); throw new HttpError(413, 'Požadavek je příliš velký.'); } chunks.push(value); } }
16| finally { reader.releaseLock(); }
17| try { return JSON.parse(Buffer.concat(chunks).toString('utf8')); } catch { throw new HttpError(400, 'Neplatný JSON.'); }
